"""Local immutable uploads. Paths are generated by the server, never accepted from clients."""
import hashlib
import json
import subprocess
from pathlib import Path

from fastapi import APIRouter, File, HTTPException, Request, UploadFile
from fastapi.responses import FileResponse
from PIL import Image, UnidentifiedImageError

from app.persistence.database import connect
from app.persistence.samples import now, uid

router = APIRouter(prefix="/api/v1/assets", tags=["assets"])


def fail(code: str, message: str, status: int = 422):
    raise HTTPException(status_code=status, detail={"code": code, "message": message})


def receive(file: UploadFile, data_dir: Path, limit: int) -> tuple[Path, str]:
    temp = data_dir / "temp" / uid("upload")
    temp.parent.mkdir(parents=True, exist_ok=True)
    sha = hashlib.sha256()
    size = 0
    try:
        with temp.open("wb") as target:
            while chunk := file.file.read(1024 * 1024):
                size += len(chunk)
                if size > limit:
                    fail("file_too_large", "文件超出大小限制", 413)
                sha.update(chunk)
                target.write(chunk)
        if size == 0:
            fail("empty_file", "文件为空")
        return temp, sha.hexdigest()
    except Exception:
        temp.unlink(missing_ok=True)
        raise


@router.post("/audio")
def upload_audio(request: Request, file: UploadFile = File()) -> dict:
    settings = request.app.state.settings
    temp, sha = receive(file, settings.data_dir, settings.max_audio_mb * 1024 * 1024)
    try:
        probe = subprocess.run([settings.ffprobe_bin, "-v", "error", "-select_streams", "a:0",
                                "-show_entries", "stream=codec_type,sample_rate:format=duration",
                                "-of", "json", str(temp)], capture_output=True, text=True, timeout=20)
        if probe.returncode:
            fail("audio_decode_failed", "无法读取音轨")
        info = json.loads(probe.stdout)
        streams = info.get("streams", [])
        duration = float(info.get("format", {}).get("duration") or 0)
        if not streams or duration <= 0 or duration > settings.max_audio_seconds:
            fail("audio_out_of_range", "录音无有效音轨或时长超出限制")
        sample_rate = int(streams[0]["sample_rate"])
        asset_id = uid("audio")
        relative = f"audio/original/{asset_id}.bin"
        target = settings.data_dir / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        temp.replace(target)
        try:
            with connect(settings.database_path) as db:
                db.execute("INSERT INTO audio_assets VALUES (?,?,?,?,?,?,?,?)", (asset_id, relative, sha, Path(file.filename or "upload").name,
                           file.content_type, duration, sample_rate, now()))
        except Exception:
            target.unlink(missing_ok=True)
            raise
        return {"id": asset_id, "sha256": sha, "duration_s": duration, "sample_rate_hz": sample_rate}
    except (FileNotFoundError, subprocess.TimeoutExpired) as exc:
        fail("ffprobe_unavailable", "音频探测工具不可用", 503)
    finally:
        temp.unlink(missing_ok=True)


@router.post("/screenshots")
def upload_screenshot(request: Request, file: UploadFile = File()) -> dict:
    settings = request.app.state.settings
    temp, sha = receive(file, settings.data_dir, 20 * 1024 * 1024)
    try:
        with Image.open(temp) as image:
            width, height = image.size
            if image.format not in {"PNG", "JPEG"} or width * height > 20_000_000 or min(width, height) <= 0:
                fail("screenshot_unsupported", "仅支持 2000 万像素以内的 PNG/JPEG")
            image_format = image.format
            image.verify()
        asset_id = uid("image")
        suffix = ".png" if image_format == "PNG" else ".jpg"
        relative = f"screenshots/original/{asset_id}{suffix}"
        target = settings.data_dir / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        temp.replace(target)
        try:
            with connect(settings.database_path) as db:
                db.execute("INSERT INTO screenshot_assets VALUES (?,?,?,?,?,?)", (asset_id, relative, sha, width, height, now()))
        except Exception:
            target.unlink(missing_ok=True)
            raise
        return {"id": asset_id, "sha256": sha, "width_px": width, "height_px": height}
    except (UnidentifiedImageError, OSError):
        fail("screenshot_decode_failed", "图片无法读取")
    finally:
        temp.unlink(missing_ok=True)


@router.get("/audio/{asset_id}")
def play_audio(asset_id: str, request: Request):
    with connect(request.app.state.settings.database_path) as db:
        row = db.execute("SELECT relative_path,mime_type FROM audio_assets WHERE id=?", (asset_id,)).fetchone()
    if not row:
        fail("asset_not_found", "音频不存在", 404)
    return FileResponse(request.app.state.settings.data_dir / row["relative_path"], media_type=row["mime_type"] or "application/octet-stream")


@router.get("/screenshots/{asset_id}")
def view_screenshot(asset_id: str, request: Request):
    with connect(request.app.state.settings.database_path) as db:
        row = db.execute("SELECT relative_path FROM screenshot_assets WHERE id=?", (asset_id,)).fetchone()
    if not row:
        fail("asset_not_found", "截图不存在", 404)
    return FileResponse(request.app.state.settings.data_dir / row["relative_path"])
